SUPPORTED = ("es", "en", "pt_BR", "zh_CN", "fr_FR")

def system_language():
    for key in ("LC_ALL", "LC_MESSAGES", "LANG", "LANGUAGE"):
        value = os.environ.get(key, "").lower().replace("-", "_")
        if value:
            for prefix, locale in (("es", "es"), ("pt_br", "pt_BR"), ("zh", "zh_CN"), ("fr", "fr_FR")):
                if value.startswith(prefix):
                    return locale
            return "en"
    return "en"

_language = "en"

def set_language(choice):
    global _language
    _language = choice if choice in SUPPORTED else system_language()

def language():
    return _language

def tr(text):
    return {"es": ES, "pt_BR": PT_BR, "zh_CN": ZH_CN, "fr_FR": FR_FR}.get(_language, EN).get(text, text)
